const yuejiangNames = Object.freeze({
  '亥':'登明','戌':'河魁','酉':'從魁','申':'傳送','未':'小吉','午':'勝光',
  '巳':'太乙','辰':'天罡','卯':'太沖','寅':'功曹','丑':'大吉','子':'神后'
});

const $ = (id) => document.getElementById(id);
let currentRows = [];
let initialized = false;

function formatYuejiang(value) {
  return value ? `${value}將：${yuejiangNames[value] || ''}` : '';
}

function formatLunar(iso) {
  try {
    const d = new Date(`${iso}T00:00:00Z`);
    return new Intl.DateTimeFormat('zh-TW-u-ca-chinese', {
      month: 'long', day: 'numeric', timeZone: 'UTC'
    }).format(d);
  } catch (error) {
    console.warn('[jishi] lunar date format failed', error);
    return '';
  }
}

function taipeiNowParts() {
  const parts = new Intl.DateTimeFormat('en-US', {
    timeZone: 'Asia/Taipei', year: 'numeric', month: 'numeric', day: 'numeric'
  }).formatToParts(new Date());
  const get = (type) => Number(parts.find((p) => p.type === type)?.value || 0);
  return { year: get('year'), month: get('month'), day: get('day') };
}

function nextMonthOf(year, month) {
  return month === 12 ? { year: year + 1, month: 1 } : { year, month: month + 1 };
}

function memberPlan() {
  const profile = window.TIANSHU_MEMBER?.profile;
  if (!profile) return null;
  if (profile.role === 'admin') return 'permanent';
  return profile.plan || 'free';
}

function getJieqiSummaryRanges(year, month, rows) {
  if (!rows.length) return [];
  const ranges = [];
  let start = rows[0].d;
  let current = rows[0].jieqi;
  for (let i = 1; i < rows.length; i += 1) {
    if (rows[i].jieqi !== current) {
      ranges.push(`${month}/${start}–${month}/${rows[i - 1].d} ${current}`);
      start = rows[i].d;
      current = rows[i].jieqi;
    }
  }
  ranges.push(`${month}/${start}–${month}/${rows.at(-1).d} ${current}`);
  return ranges;
}

function cell(value) { return value ?? ''; }

function renderRows(rows) {
  const today = new Intl.DateTimeFormat('en-CA', {
    timeZone: 'Asia/Taipei', year: 'numeric', month: '2-digit', day: '2-digit'
  }).format(new Date());

  $('ftRows').innerHTML = rows.map((r) => {
    const note = r.jiejieTime ? `本日交節：交節後採用「${r.jieqi}」與「${r.yuejiang}將」` : '';
    const rowClass = r.date === today ? ' class="is-today"' : '';
    return `<tr${rowClass}>
      <td>${r.m}月${r.d}日${r.date === today ? '<span class="today-tag">今日</span>' : ''}</td>
      <td>${cell(r.dunju)}</td><td>${cell(r.jieqi)}</td><td>${formatYuejiang(r.yuejiang)}</td>
      <td>${cell(r.jiejieTime)}</td><td>${formatLunar(r.date)}</td><td>${cell(r.ganzhi)}</td>
      <td>${cell(r.week)}</td><td>${cell(r.yibao)}</td><td>${cell(r.xingxiu)}</td>
      <td>${cell(r.jianchu)}</td><td>${cell(r.guideng)}</td><td>${cell(r.gangse)}</td>
      <td>${cell(r.tiangang)}</td><td>${cell(r.ride)}</td><td>${cell(r.zhide)}</td>
      <td>${cell(r.guise)}</td><td class="jishi-highlight">${cell(r.fourTime)}</td>
      <td>${cell(r.doubing)}</td><td class="jishi-note-cell">${note}</td>
    </tr>`;
  }).join('');
}

function renderSummary(year, month, rows) {
  if (!rows.length) {
    $('ftTitle').textContent = `${year}年${month}月份資料尚未開放`;
    $('ftRange').textContent = '尚未開放';
    $('ftQuick').innerHTML = '<article class="jishi-stat"><span>狀態</span><strong>待更新</strong></article>';
    $('ftRows').innerHTML = '<tr><td colspan="20" class="jishi-empty">本月份四大吉時資料尚未開放，請待管理員更新。</td></tr>';
    return;
  }
  const ranges = getJieqiSummaryRanges(year, month, rows);
  const yuejiang = [...new Set(rows.map((r) => r.yuejiang).filter(Boolean))].map(formatYuejiang);
  const transitionRows = rows.filter((r) => r.jiejieTime);
  $('ftTitle').textContent = `${year}年${month}月份 六壬擇日四大吉時表`;
  $('ftRange').textContent = `${year}年${month}月`;
  $('ftQuick').innerHTML = `
    <article class="jishi-stat"><span>本月日數</span><strong>${rows.length}</strong></article>
    <article class="jishi-stat"><span>節氣區間</span><div>${ranges.map((v) => `<b>${v}</b>`).join('')}</div></article>
    <article class="jishi-stat"><span>月將</span><div>${yuejiang.map((v) => `<b>${v}</b>`).join('')}</div></article>
    <article class="jishi-stat"><span>交節日</span><strong>${transitionRows.length}</strong></article>
    <article class="jishi-stat"><span>月初斗柄</span><strong>${rows[0]?.doubing || '—'}</strong></article>
    <article class="jishi-stat"><span>月底斗柄</span><strong>${rows.at(-1)?.doubing || '—'}</strong></article>`;
}

function render() {
  const year = Number($('ftYear').value);
  const month = Number($('ftMonth').value);
  currentRows = FOUR_TIME_DATA.filter((r) => r.y === year && r.m === month);
  renderSummary(year, month, currentRows);
  if (currentRows.length) renderRows(currentRows);
}

function availableMonths(year) {
  return FOUR_TIME_META.availableMonths[year] || [];
}

function choosePreferredMonth(year, months, previous) {
  const now = taipeiNowParts();
  if (months.includes(previous)) return previous;
  if (year === now.year && months.includes(now.month)) return now.month;
  return months[0];
}

function fillAllMonths(yearSelect, monthSelect) {
  const year = Number(yearSelect.value);
  const months = availableMonths(year);
  const previous = Number(monthSelect.value);
  monthSelect.replaceChildren();
  months.forEach((month) => monthSelect.add(new Option(`${month}月`, String(month))));
  const preferred = choosePreferredMonth(year, months, previous);
  if (preferred) monthSelect.value = String(preferred);
}

function allAvailableTargets() {
  return FOUR_TIME_META.years.flatMap((year) => availableMonths(year).map((month) => ({ year, month })));
}

function freeTargets() {
  const now = taipeiNowParts();
  const next = nextMonthOf(now.year, now.month);
  return [{ year: now.year, month: now.month, label: '當月份' }, { ...next, label: '下一月份' }];
}

function targetHasData(target) {
  return availableMonths(target.year).includes(target.month);
}

function setAvailability(strong, small) {
  const box = document.querySelector('.jishi-availability');
  if (!box) return;
  const strongEl = box.querySelector('strong');
  const smallEl = box.querySelector('small');
  if (strongEl) strongEl.textContent = strong;
  if (smallEl) smallEl.textContent = small;
}

function fillFreeSelectors(yearSelect, monthSelect) {
  const targets = freeTargets();
  const current = targets[0];
  const next = targets[1];
  const previousYear = Number(yearSelect.value);
  const previousMonth = Number(monthSelect.value);
  const allowedYears = [...new Set(targets.map((t) => t.year))];
  yearSelect.replaceChildren(...allowedYears.map((year) => new Option(String(year), String(year))));
  const preferredTarget = targets.find((t) => t.year === previousYear && t.month === previousMonth) || current;
  yearSelect.value = String(preferredTarget.year);

  const refreshMonths = () => {
    const y = Number(yearSelect.value);
    const yearTargets = targets.filter((t) => t.year === y);
    const prior = Number(monthSelect.value);
    monthSelect.replaceChildren();
    yearTargets.forEach((t) => {
      const suffix = targetHasData(t) ? '' : '（資料待更新）';
      monthSelect.add(new Option(`${t.month}月（${t.label}）${suffix}`, String(t.month)));
    });
    const keep = yearTargets.some((t) => t.month === prior) ? prior : yearTargets[0]?.month;
    if (keep) monthSelect.value = String(keep);
  };

  refreshMonths();
  if (Number(yearSelect.value) === preferredTarget.year) monthSelect.value = String(preferredTarget.month);
  yearSelect.disabled = allowedYears.length === 1;
  monthSelect.disabled = false;
  yearSelect.onchange = () => { refreshMonths(); render(); };
  monthSelect.onchange = render;

  const rangeText = `${current.year}/${current.month}、${next.year}/${next.month}`;
  const availability = targets.every(targetHasData) ? '兩個月份皆已有資料' : '部分月份資料尚待更新';
  setAvailability(rangeText, `一般會員｜${availability}`);
  const hint = $('jishiPlanHint');
  if (hint) hint.textContent = '一般會員｜僅可查當月份與下一月份';
  render();
}

function fillFullSelectors(yearSelect, monthSelect, profile) {
  const previousYear = Number(yearSelect.value);
  const previousMonth = Number(monthSelect.value);
  yearSelect.replaceChildren(...FOUR_TIME_META.years.map((year) => new Option(String(year), String(year))));
  const now = taipeiNowParts();
  const defaultYear = FOUR_TIME_META.years.includes(previousYear)
    ? previousYear
    : (FOUR_TIME_META.years.includes(now.year) ? now.year : FOUR_TIME_META.years[0]);
  yearSelect.value = String(defaultYear);
  fillAllMonths(yearSelect, monthSelect);
  if (availableMonths(defaultYear).includes(previousMonth)) monthSelect.value = String(previousMonth);
  yearSelect.disabled = FOUR_TIME_META.years.length === 1;
  monthSelect.disabled = false;
  yearSelect.onchange = () => { fillAllMonths(yearSelect, monthSelect); render(); };
  monthSelect.onchange = render;

  const targets = allAvailableTargets();
  const first = targets[0], last = targets.at(-1);
  const range = first && last ? `${first.year}/${first.month}–${last.year}/${last.month}` : '尚無資料';
  const roleText = profile?.role === 'admin' ? '管理員' : (memberPlan() === 'formal' ? '正式會員' : '永久會員');
  setAvailability(range, `${roleText}｜目前資料庫全部月份`);
  const hint = $('jishiPlanHint');
  if (hint) hint.textContent = `${roleText}｜可查目前資料庫全部月份`;
  render();
}

function applyPlanRestrictions() {
  if (!initialized) return;
  const profile = window.TIANSHU_MEMBER?.profile;
  if (!profile) return;
  const yearSelect = $('ftYear');
  const monthSelect = $('ftMonth');
  const plan = memberPlan();
  if (plan === 'free' && profile.role !== 'admin') fillFreeSelectors(yearSelect, monthSelect);
  else fillFullSelectors(yearSelect, monthSelect, profile);
}

function init() {
  if (initialized) return;
  initialized = true;
  const yearSelect = $('ftYear');
  const monthSelect = $('ftMonth');

  // Temporary initial fill while auth/profile is loading; the member-ready event applies the final plan window.
  FOUR_TIME_META.years.forEach((year) => yearSelect.add(new Option(String(year), String(year))));
  const now = taipeiNowParts();
  yearSelect.value = String(FOUR_TIME_META.years.includes(now.year) ? now.year : FOUR_TIME_META.years[0]);
  fillAllMonths(yearSelect, monthSelect);
  yearSelect.disabled = FOUR_TIME_META.years.length === 1;
  yearSelect.onchange = () => { fillAllMonths(yearSelect, monthSelect); render(); };
  monthSelect.onchange = render;
  $('ftPrint').addEventListener('click', () => window.print());
  render();
  applyPlanRestrictions();
}

function startJishiPage() {
  init();
  applyPlanRestrictions();
}

function bootJishiWithStableMember() {
  if (window.TIANSHU_MEMBER?.profile) {
    startJishiPage();
    return;
  }
  const timer = setInterval(() => {
    if (!window.TIANSHU_MEMBER?.profile) return;
    clearInterval(timer);
    startJishiPage();
  }, 40);
}

if (document.readyState === 'loading') {
  document.addEventListener('DOMContentLoaded', bootJishiWithStableMember, { once: true });
} else {
  bootJishiWithStableMember();
}

window.addEventListener('tianshu:plan-ready', () => {
  if (window.TIANSHU_MEMBER?.profile) startJishiPage();
});

window.__TIANSHU_JISHI_VERSION__ = '3.0.0';
